using AcxiomCRM.Web.Data; using AcxiomCRM.Web.Models; using AcxiomCRM.Web.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Web.Controllers;
[Authorize] public class LeadsController:Controller{readonly ApplicationDbContext db;readonly UserManager<ApplicationUser> um;readonly AuditService audit;public LeadsController(ApplicationDbContext d,UserManager<ApplicationUser> u,AuditService a){db=d;um=u;audit=a;}string U=>um.GetUserId(User)!;bool Priv=>User.IsInRole("Admin")||User.IsInRole("Manager");
public async Task<IActionResult> Index(string? q,LeadStatus? status){var x=db.Leads.Include(l=>l.AssignedTo).AsQueryable();if(!Priv)x=x.Where(l=>l.AssignedToId==U);if(!string.IsNullOrWhiteSpace(q))x=x.Where(l=>l.LeadName.Contains(q)||l.CompanyName.Contains(q));if(status.HasValue)x=x.Where(l=>l.Status==status);return View(await x.OrderByDescending(l=>l.CreatedAt).ToListAsync());}
public IActionResult Create()=>View(new LeadVm());
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(LeadVm vm){if(!ModelState.IsValid)return View(vm);var l=new Lead{LeadCode="LED-"+Random.Shared.Next(100000,999999),LeadName=vm.LeadName,Email=vm.Email,Phone=vm.Phone,CompanyName=vm.CompanyName,Source=vm.Source,Status=vm.Status,Priority=vm.Priority,ExpectedValue=vm.ExpectedValue,AssignedToId=Priv&&vm.AssignedToId!=null?vm.AssignedToId:U};db.Leads.Add(l);await db.SaveChangesAsync();await audit.LogAsync("CREATE","Lead",l.Id.ToString(),null,l.LeadName,U);return RedirectToAction(nameof(Index));}
public async Task<IActionResult>Edit(int id){var l=await db.Leads.FindAsync(id);if(l==null)return NotFound();if(!Priv&&l.AssignedToId!=U)return Forbid();return View(new LeadVm{Id=l.Id,LeadName=l.LeadName,Email=l.Email,Phone=l.Phone,CompanyName=l.CompanyName,Source=l.Source,Status=l.Status,Priority=l.Priority,ExpectedValue=l.ExpectedValue,AssignedToId=l.AssignedToId});}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Edit(int id,LeadVm vm){var l=await db.Leads.FindAsync(id);if(l==null)return NotFound();if(!Priv&&l.AssignedToId!=U)return Forbid();if(!ModelState.IsValid)return View(vm);var allowed=new Dictionary<LeadStatus,LeadStatus[]>{{LeadStatus.New,new[]{LeadStatus.Contacted,LeadStatus.Qualified,LeadStatus.Unqualified,LeadStatus.Lost}},{LeadStatus.Contacted,new[]{LeadStatus.Qualified,LeadStatus.Unqualified,LeadStatus.Lost}},{LeadStatus.Qualified,new[]{LeadStatus.Converted,LeadStatus.Lost}},{LeadStatus.Unqualified,Array.Empty<LeadStatus>()},{LeadStatus.Converted,Array.Empty<LeadStatus>()},{LeadStatus.Lost,new[]{LeadStatus.Contacted,LeadStatus.Qualified}}};if(vm.Status!=l.Status&&!allowed.GetValueOrDefault(l.Status,Array.Empty<LeadStatus>()).Contains(vm.Status)){ModelState.AddModelError("Status",$"Invalid transition from {l.Status} to {vm.Status}.");return View(vm);}var old=l.Status.ToString();l.LeadName=vm.LeadName;l.Email=vm.Email;l.Phone=vm.Phone;l.CompanyName=vm.CompanyName;l.Source=vm.Source;l.Status=vm.Status;l.Priority=vm.Priority;l.ExpectedValue=vm.ExpectedValue;if(Priv&&vm.AssignedToId!=null)l.AssignedToId=vm.AssignedToId;await db.SaveChangesAsync();await audit.LogAsync("UPDATE","Lead",id.ToString(),old,l.Status.ToString(),U);if(l.Status==LeadStatus.Converted)await audit.LogAsync("CONVERT","Lead",id.ToString(),null,"Converted",U);return RedirectToAction(nameof(Index));}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Delete(int id){var l=await db.Leads.FindAsync(id);if(l==null)return NotFound();if(!Priv&&l.AssignedToId!=U)return Forbid();l.Status=LeadStatus.Lost;await db.SaveChangesAsync();await audit.LogAsync("DEACTIVATE","Lead",id.ToString(),null,"Lost",U);return RedirectToAction(nameof(Index));}
[HttpPost,ValidateAntiForgeryToken]
public async Task<IActionResult> Convert(int id){
    var l=await db.Leads.FindAsync(id); if(l==null)return NotFound(); if(!Priv&&l.AssignedToId!=U)return Forbid();
    if(l.Status!=LeadStatus.Qualified){TempData["Error"]="Only qualified leads can be converted.";return RedirectToAction(nameof(Index));}
    var customer=await db.Customers.FirstOrDefaultAsync(c=>c.Email==l.Email||c.Phone==l.Phone);
    if(customer==null){customer=new Customer{CustomerCode="CUS-"+Random.Shared.Next(100000,999999),CustomerName=l.LeadName,Email=l.Email,Phone=l.Phone,CompanyName=l.CompanyName,Status=CustomerStatus.Active,OwnerId=l.AssignedToId};db.Customers.Add(customer);await db.SaveChangesAsync();}
    var opportunity=new Opportunity{OpportunityName=$"Converted - {l.CompanyName}",CustomerId=customer.Id,LeadId=l.Id,Amount=Math.Max(1,l.ExpectedValue),Probability=25,Stage=OpportunityStage.Qualification,Status=OpportunityStatus.Open,ExpectedCloseDate=DateTime.UtcNow.Date.AddDays(30),OwnerId=l.AssignedToId};
    db.Opportunities.Add(opportunity);l.Status=LeadStatus.Converted;l.CustomerId=customer.Id;await db.SaveChangesAsync();await audit.LogAsync("CONVERT","Lead",l.Id.ToString(),"Qualified",$"Converted to Customer {customer.Id}, Opportunity {opportunity.Id}",U);return RedirectToAction(nameof(Index));
}

}
